public sealed class FinancialAccount { public Guid Id { get; set; } public Guid TenantId { get; set; } public string Name { get; set; } = ""; public string Currency { get; set; } = "ARS"; public FinancialAccountType Type { get; set; } public decimal OpeningBalance { get; set; } public bool IsActive { get; set; } = true; public DateTime CreatedAtUtc { get; set; } }
public sealed class FinancialMovement { public Guid Id { get; set; } public Guid TenantId { get; set; } public Guid AccountId { get; set; } public FinancialMovementKind Kind { get; set; } public decimal Amount { get; set; } public string Currency { get; set; } = "ARS"; public DateTime OperationDateUtc { get; set; } public string Description { get; set; } = ""; public string? ExternalReference { get; set; } public Guid? TransferId { get; set; } public decimal? ReportedBalance { get; set; } public FinancialReconciliationStatus ReconciliationStatus { get; set; } = FinancialReconciliationStatus.Available; public Guid? ConceptId { get; set; } public Guid? ConceptRuleId { get; set; } public FinancialClassificationStatus ClassificationStatus { get; set; } = FinancialClassificationStatus.Imported; public string? ClassificationNote { get; set; } public DateTime? ClassifiedAtUtc { get; set; } public Guid? SuggestedCounterpartyId { get; set; } public string? SuggestedCounterpartyType { get; set; } public string? LinkedEntityType { get; set; } public Guid? LinkedEntityId { get; set; } public FinancialMovementOrigin Origin { get; set; } = FinancialMovementOrigin.System; public Guid? ImportId { get; set; } public Guid? MatchedMovementId { get; set; } public DateTime CreatedAtUtc { get; set; } }
public sealed class DocumentSequence { public Guid Id { get; set; } public Guid TenantId { get; set; } public string DocumentType { get; set; } = ""; public string Prefix { get; set; } = ""; public int NextNumber { get; set; } = 1; public DateTime UpdatedAtUtc { get; set; } }
public sealed class CustomerAdvance { public Guid Id { get; set; } public Guid TenantId { get; set; } public Guid CustomerId { get; set; } public Guid CollectionReceiptId { get; set; } public decimal Amount { get; set; } public decimal RemainingAmount { get; set; } public string Currency { get; set; } = "ARS"; public DateTime CreatedAtUtc { get; set; } }
public sealed class BankStatementImport { public Guid Id { get; set; } public Guid TenantId { get; set; } public Guid AccountId { get; set; } public string? FileName { get; set; } public string FileHash { get; set; } = ""; public DateTime? PeriodStart { get; set; } public DateTime? PeriodEnd { get; set; } public decimal? DeclaredOpeningBalance { get; set; } public decimal? DeclaredClosingBalance { get; set; } public decimal? ComputedClosingBalance { get; set; } public int RowsTotal { get; set; } public int RowsImported { get; set; } public int RowsDuplicated { get; set; } public int RowsRejected { get; set; } public string Status { get; set; } = "Balanced"; public DateTime CreatedAtUtc { get; set; } public string? CreatedBy { get; set; } }
public sealed class CollectionReceipt { public Guid Id { get; set; } public Guid TenantId { get; set; } public Guid AccountId { get; set; } public Guid? CustomerId { get; set; } public Guid? InvoiceId { get; set; } public string ReceiptNumber { get; set; } = ""; public decimal Amount { get; set; } public decimal AdvanceAmount { get; set; } public string Currency { get; set; } = "ARS"; public string? InvoiceCurrency { get; set; } public decimal? InvoiceAmount { get; set; } public decimal? InvoiceExchangeRate { get; set; } public decimal? PaymentExchangeRate { get; set; } public decimal? SuggestedAdjustmentArs { get; set; } public string? SuggestedAdjustmentType { get; set; } public decimal? ExchangeDifferenceAmount { get; set; } public DateTime ReceiptDateUtc { get; set; } public string Description { get; set; } = ""; public string Status { get; set; } = "Confirmed"; public string? VoidReason { get; set; } public DateTime? VoidedAtUtc { get; set; } public DateTime CreatedAtUtc { get; set; } }
public sealed record CreateAccountRequest(string Name, string Currency, FinancialAccountType Type, decimal OpeningBalance);
public sealed class CollectionReceiptLine { public Guid Id { get; set; } public Guid TenantId { get; set; } public Guid ReceiptId { get; set; } public string Method { get; set; } = ""; public decimal Amount { get; set; } public string Currency { get; set; } = "ARS"; public Guid? AccountId { get; set; } public Guid? BankMovementId { get; set; } public Guid? ChequeId { get; set; } public Guid? ConceptId { get; set; } public string? RetentionType { get; set; } public string? RetentionCertificate { get; set; } public string? Notes { get; set; } public DateTime CreatedAtUtc { get; set; } }
public sealed class CollectionReceiptImputation { public Guid Id { get; set; } public Guid TenantId { get; set; } public Guid ReceiptId { get; set; } public Guid InvoiceId { get; set; } public string InvoiceNumber { get; set; } = ""; public decimal InvoiceTotal { get; set; } public decimal AmountImputed { get; set; } public string Status { get; set; } = "Active"; public DateTime CreatedAtUtc { get; set; } }
public sealed record CreateMovementRequest(Guid AccountId, FinancialMovementKind Kind, decimal Amount, string Currency, DateTime OperationDateUtc, string Description, string? ExternalReference);
public sealed record TransferRequest(Guid FromAccountId, Guid ToAccountId, decimal Amount, string Currency, DateTime OperationDateUtc, string Description);

public sealed class PaymentOrder { public Guid Id { get; set; } public Guid TenantId { get; set; } public Guid? SupplierId { get; set; } public string SupplierName { get; set; } = ""; public string? SupplierTaxId { get; set; } public string OrderNumber { get; set; } = ""; public decimal Amount { get; set; } public decimal AdvanceAmount { get; set; } public string Currency { get; set; } = "ARS"; public DateTime PaymentDateUtc { get; set; } public string? Notes { get; set; } public string Status { get; set; } = "Confirmed"; public string? VoidReason { get; set; } public DateTime? VoidedAtUtc { get; set; } public DateTime CreatedAtUtc { get; set; } }
public sealed class PaymentOrderLine { public Guid Id { get; set; } public Guid TenantId { get; set; } public Guid PaymentOrderId { get; set; } public string Method { get; set; } = ""; public decimal Amount { get; set; } public string Currency { get; set; } = "ARS"; public Guid? AccountId { get; set; } public Guid? BankMovementId { get; set; } public Guid? ChequeId { get; set; } public Guid? ConceptId { get; set; } public string? RetentionType { get; set; } public string? RetentionCertificate { get; set; } public string? Notes { get; set; } public DateTime CreatedAtUtc { get; set; } }
public sealed class PaymentOrderImputation { public Guid Id { get; set; } public Guid TenantId { get; set; } public Guid PaymentOrderId { get; set; } public Guid PurchaseInvoiceId { get; set; } public string InvoiceNumber { get; set; } = ""; public decimal InvoiceTotal { get; set; } public decimal AmountImputed { get; set; } public DateTime CreatedAtUtc { get; set; } }

public sealed class FinanceDbContext(DbContextOptions<FinanceDbContext> options) : DbContext(options)
{
    public const string Schema = "finance";
    public DbSet<FinancialAccount> Accounts => Set<FinancialAccount>();
    public DbSet<FinancialMovement> Movements => Set<FinancialMovement>();
    public DbSet<CollectionReceipt> CollectionReceipts => Set<CollectionReceipt>();
    public DbSet<CollectionReceiptLine> CollectionReceiptLines => Set<CollectionReceiptLine>();
    public DbSet<CollectionReceiptImputation> CollectionReceiptImputations => Set<CollectionReceiptImputation>();
    public DbSet<ReceivedCheque> ReceivedCheques => Set<ReceivedCheque>();
    public DbSet<FinancialConcept> FinancialConcepts => Set<FinancialConcept>();
    public DbSet<FinancialConceptRule> FinancialConceptRules => Set<FinancialConceptRule>();
    public DbSet<PaymentOrder> PaymentOrders => Set<PaymentOrder>();
    public DbSet<PaymentOrderLine> PaymentOrderLines => Set<PaymentOrderLine>();
    public DbSet<PaymentOrderImputation> PaymentOrderImputations => Set<PaymentOrderImputation>();
    public DbSet<BankStatementImport> BankStatementImports => Set<BankStatementImport>();
    public DbSet<DocumentSequence> DocumentSequences => Set<DocumentSequence>();
    public DbSet<CustomerAdvance> CustomerAdvances => Set<CustomerAdvance>();
    protected override void OnModelCreating(ModelBuilder modelBuilder) { modelBuilder.HasDefaultSchema(Schema); modelBuilder.Entity<FinancialAccount>(b => { b.ToTable("FinancialAccounts"); b.HasKey(x => x.Id); b.Property(x => x.Name).HasMaxLength(180).IsRequired(); b.Property(x => x.Currency).HasMaxLength(8).IsRequired(); b.Property(x => x.OpeningBalance).HasPrecision(18, 2); b.HasIndex(x => new { x.TenantId, x.Name }); }); modelBuilder.Entity<FinancialMovement>(b => { b.ToTable("FinancialMovements"); b.HasKey(x => x.Id); b.Property(x => x.Amount).HasPrecision(18, 2); b.Property(x => x.Currency).HasMaxLength(8); b.Property(x => x.Description).HasMaxLength(500); b.Property(x => x.ExternalReference).HasMaxLength(180); b.HasIndex(x => new { x.TenantId, x.AccountId, x.OperationDateUtc }); b.HasIndex(x => x.ImportId); }); modelBuilder.Entity<BankStatementImport>(b => { b.ToTable("BankStatementImports"); b.HasKey(x => x.Id); b.Property(x => x.FileName).HasMaxLength(260); b.Property(x => x.FileHash).HasMaxLength(64).IsRequired(); b.Property(x => x.Status).HasMaxLength(20).IsRequired(); b.Property(x => x.DeclaredOpeningBalance).HasPrecision(18, 2); b.Property(x => x.DeclaredClosingBalance).HasPrecision(18, 2); b.Property(x => x.ComputedClosingBalance).HasPrecision(18, 2); b.Property(x => x.CreatedBy).HasMaxLength(120); b.HasIndex(x => new { x.TenantId, x.AccountId, x.FileHash }).IsUnique(); }); modelBuilder.Entity<CollectionReceipt>(b => { b.ToTable("CollectionReceipts"); b.HasKey(x => x.Id); b.Property(x => x.Amount).HasPrecision(18, 2); b.Property(x => x.Currency).HasMaxLength(8).IsRequired(); b.Property(x => x.ReceiptNumber).HasMaxLength(40).IsRequired(); b.Property(x => x.Description).HasMaxLength(500).IsRequired(); b.Property(x => x.Status).HasMaxLength(30).IsRequired(); }); }
}

public static class DependencyInjection
{
    public static IServiceCollection AddFinanceModule(this IServiceCollection services, IConfiguration configuration)
    {
        services.AddFinanceApplication();
        services.AddMediatR(cfg => cfg.RegisterServicesFromAssembly(typeof(FinanceDbContext).Assembly));
        services.AddTenantDbContext<FinanceDbContext>(FinanceDbContext.Schema);
        return services;
    }
    public static IEndpointRouteBuilder MapFinanceModule(this IEndpointRouteBuilder endpoints)
    { var group = endpoints.MapGroup("/api/v1/finance").WithTags("Finance").RequirePolicyOnWrites("RequireFinance"); group.MapGet("/accounts", async (FinanceDbContext db, ITenantContext tenant, CancellationToken ct) => { var id = tenant.TenantId.Value; var accounts = await db.Accounts.AsNoTracking().Where(x => x.TenantId == id).OrderBy(x => x.Name).ToListAsync(ct); var balances = await db.Movements.AsNoTracking().Where(x => x.TenantId == id).GroupBy(x => x.AccountId).Select(g => new { AccountId = g.Key, Credit = g.Where(x => x.Kind == FinancialMovementKind.Credit).Sum(x => (decimal?)x.Amount) ?? 0, Debit = g.Where(x => x.Kind == FinancialMovementKind.Debit).Sum(x => (decimal?)x.Amount) ?? 0 }).ToDictionaryAsync(x => x.AccountId, ct); return Results.Ok(accounts.Select(a => new { a.Id, a.Name, a.Currency, a.Type, IsActive = a.IsActive, Balance = a.OpeningBalance + (balances.TryGetValue(a.Id, out var b) ? b.Credit - b.Debit : 0) })); }); group.MapPost("/accounts", async (CreateAccountRequest body, FinanceDbContext db, ITenantContext tenant, CancellationToken ct) => { var id = tenant.TenantId.Value; var account = new FinancialAccount { Id = Guid.NewGuid(), TenantId = id, Name = body.Name.Trim(), Currency = body.Currency.Trim().ToUpperInvariant(), Type = body.Type, OpeningBalance = body.OpeningBalance, CreatedAtUtc = DateTime.UtcNow }; db.Accounts.Add(account); await db.SaveChangesAsync(ct); return Results.Created($"/api/v1/finance/accounts/{account.Id}", account); }); group.MapPost("/movements", async (CreateMovementRequest body, FinanceDbContext db, ITenantContext tenant, CancellationToken ct) => { var id = tenant.TenantId.Value; if (!await db.Accounts.AnyAsync(x => x.Id == body.AccountId && x.TenantId == id && x.IsActive, ct)) return Results.NotFound("Cuenta financiera inexistente."); var movement = new FinancialMovement { Id = Guid.NewGuid(), TenantId = id, AccountId = body.AccountId, Kind = body.Kind, Amount = body.Amount, Currency = body.Currency.Trim().ToUpperInvariant(), OperationDateUtc = body.OperationDateUtc, Description = body.Description.Trim(), ExternalReference = body.ExternalReference, CreatedAtUtc = DateTime.UtcNow }; db.Movements.Add(movement); await db.SaveChangesAsync(ct); return Results.Created($"/api/v1/finance/movements/{movement.Id}", movement); }); group.MapPost("/transfers", async (TransferRequest body, FinanceDbContext db, ITenantContext tenant, CancellationToken ct) => { var id = tenant.TenantId.Value; if (body.FromAccountId == body.ToAccountId || body.Amount <= 0) return Results.BadRequest("Indicá cuentas distintas y un importe mayor a cero."); var accounts = await db.Accounts.Where(x => x.TenantId == id && x.IsActive && (x.Id == body.FromAccountId || x.Id == body.ToAccountId)).ToListAsync(ct); var from = accounts.SingleOrDefault(x => x.Id == body.FromAccountId); var to = accounts.SingleOrDefault(x => x.Id == body.ToAccountId); if (from is null || to is null) return Results.NotFound("Una de las cuentas no existe o está inactiva."); var currency = body.Currency.Trim().ToUpperInvariant(); if (from.Currency != currency || to.Currency != currency) return Results.BadRequest("La moneda debe coincidir con ambas cuentas."); var balances = await db.Movements.Where(x => x.TenantId == id && x.AccountId == from.Id).GroupBy(x => x.AccountId).Select(g => g.Sum(x => x.Kind == FinancialMovementKind.Credit ? x.Amount : -x.Amount)).SingleOrDefaultAsync(ct); if (from.OpeningBalance + balances < body.Amount) return Results.BadRequest("La cuenta de origen no tiene saldo suficiente."); var transferId = Guid.NewGuid(); var debitTransfer = new FinancialMovement { Id = Guid.NewGuid(), TenantId = id, AccountId = from.Id, Kind = FinancialMovementKind.Debit, Amount = body.Amount, Currency = currency, OperationDateUtc = body.OperationDateUtc, Description = body.Description.Trim(), ExternalReference = $"TRANSFER:{transferId}", TransferId = transferId, CreatedAtUtc = DateTime.UtcNow }; var creditTransfer = new FinancialMovement { Id = Guid.NewGuid(), TenantId = id, AccountId = to.Id, Kind = FinancialMovementKind.Credit, Amount = body.Amount, Currency = currency, OperationDateUtc = body.OperationDateUtc, Description = body.Description.Trim(), ExternalReference = $"TRANSFER:{transferId}", TransferId = transferId, CreatedAtUtc = DateTime.UtcNow }; FinanceSystemMovementHelper.ApplySystemDefaults(debitTransfer, from); FinanceSystemMovementHelper.ApplySystemDefaults(creditTransfer, to); var transferConceptId = await db.FinancialConcepts.Where(x => x.TenantId == id && x.Code == "TRANSFERENCIA_PROPIA").Select(x => (Guid?)x.Id).SingleOrDefaultAsync(ct); debitTransfer.ConceptId = transferConceptId; creditTransfer.ConceptId = transferConceptId; db.Movements.AddRange(debitTransfer, creditTransfer); await db.SaveChangesAsync(ct); return Results.Ok(new { transferId, amount = body.Amount, currency }); }); FinanceImport.MapFinanceImportEndpoints(endpoints); FinanceReconciliation.MapFinanceReconciliationEndpoints(endpoints); return endpoints; }
}



